description:
Write `retry(fn, attempts, sleep, delay=1.0)`:

- call `fn()`; if it returns, give back its result;
- if it raises an exception, call `sleep(seconds)` and try again, doubling the delay each time (1, 2, 4 ... with the default delay);
- after `attempts` failed calls, raise the last exception (do not sleep after the final failure);
- `attempts` below 1 raises `ValueError` without calling `fn`.

`sleep` is passed in so tests never wait: the tests give it a `Mock` and check how it was called.

solution.solution.py:
def retry(fn, attempts, sleep, delay=1.0):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    wait = delay
    for attempt in range(1, attempts + 1):
        try:
            return fn()
        except Exception:
            if attempt == attempts:
                raise
            sleep(wait)
            wait *= 2

unitTests:
from unittest.mock import Mock, call

@test("returns the first success without sleeping")
def _():
    fn = Mock(return_value=42)
    sleep = Mock()
    check_eq(retry(fn, 3, sleep), 42)
    check_eq(fn.call_count, 1)
    check_eq(sleep.call_count, 0)

@test("retries with doubling delays")
def _():
    fn = Mock(side_effect=[OSError("a"), OSError("b"), "ok"])
    sleep = Mock()
    check_eq(retry(fn, 5, sleep), "ok")
    check_eq(sleep.call_args_list, [call(1.0), call(2.0)])

@test("raises the last error after the final attempt")
def _():
    fn = Mock(side_effect=[OSError("first"), OSError("last")])
    sleep = Mock()
    try:
        retry(fn, 2, sleep, delay=0.5)
        check(False, "should have raised")
    except OSError as e:
        check_eq(str(e), "last")
    check_eq(sleep.call_args_list, [call(0.5)])

@test("attempts below 1 refused without calling fn")
def _():
    fn = Mock()
    check_raises(ValueError, retry, fn, 0, Mock())
    check_eq(fn.call_count, 0)

